import ch.qos.logback.core.read.ListAppender;

/**
 * Keeps the original single-transaction quoted-data workload as an enabled autogrow regression. The paired tests differ
 * only by whether a read-committed triple-term cursor is held while the identical writer transaction commits.
 */
@ResourceLock("lmdb-resize-loggers")
class LmdbAutogrowSingleCommitIT {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:lmdb-autogrow:isolation:predicate");
	private static final int ROWS = 32_768;
	private static final int VALUE_LENGTH = 160;

	@TempDir
	Path dataDir;

	@Test
	@Timeout(60)
	void singleQuotedCommitCompletesWithHeldReadCommittedReader() throws Exception {
		exerciseSingleQuotedCommit(true);
	}

	@Test
	@Timeout(60)
	void singleQuotedCommitCompletesWithoutHeldReader() throws Exception {
		exerciseSingleQuotedCommit(false);
	}

	private void exerciseSingleQuotedCommit(boolean holdReader) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open()) {
				int initialRows = seedQuotedTripleTerms(repository, ROWS);
				List<String> beforeGrowth = resizeLogs.resizeMessages();
				resizeLogs.clear();
				if (holdReader) {
					try (SailDataset dataset = store.getBackingStore()
							.getExplicitSailSource()
							.dataset(IsolationLevels.READ_COMMITTED);
							CloseableIteration<? extends TripleTerm> triples = dataset.getTriples(null, PREDICATE,
									null);
							SailRepositoryConnection writer = repository.getConnection()) {
						assertThat(triples.hasNext()).as("preloaded quoted triples must be visible").isTrue();
						triples.next();
						commitSingleGrowth(writer, repository, initialRows, beforeGrowth, resizeLogs);
						int remaining = 0;
						while (triples.hasNext()) {
							triples.next();
							remaining++;
						}
						assertThat(remaining).as("the held read-committed cursor must retain the preloaded quoted rows")
								.isEqualTo(initialRows - 1);
					}
				} else {
					try (SailRepositoryConnection writer = repository.getConnection()) {
						commitSingleGrowth(writer, repository, initialRows, beforeGrowth, resizeLogs);
					}
				}

				assertThat(resizeLogs.valueResizeMessages())
						.as("a successful single commit must log the value-map resize")
						.isNotEmpty();
				assertThat(countRows(repository)).as("a successful single commit must preserve every input row")
						.isEqualTo(initialRows + ROWS);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void commitSingleGrowth(SailRepositoryConnection writer, SailRepository repository, int initialRows,
			List<String> beforeGrowth, ResizeLogCapture resizeLogs) {
		writer.begin(IsolationLevels.READ_COMMITTED);
		try {
			addRows(writer, "quoted-growth-subject:", "quoted-growth-value:", 0, ROWS);
			writer.commit();
		} catch (RepositoryException failure) {
			failure.addSuppressed(new AssertionError(
					"single commit map diagnostics; before growth=" + beforeGrowth + "; after growth="
							+ resizeLogs.resizeMessages()));
			try {
				writer.rollback();
				int recoveredRows = countRows(repository);
				if (recoveredRows != initialRows) {
					failure.addSuppressed(new AssertionError(
							"failed single commit did not preserve the preloaded row count: " + recoveredRows));
				} else {
					failure.addSuppressed(new AssertionError("rollback recovery passed; rows=" + recoveredRows));
				}
			} catch (RepositoryException recoveryFailure) {
				failure.addSuppressed(recoveryFailure);
			}
			throw failure;
		}
	}

	private static int seedQuotedTripleTerms(SailRepository repository, int count) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			for (int i = 0; i < count; i++) {
				TripleTerm quoted = VF.createTripleTerm(
						VF.createIRI("urn:lmdb-autogrow:quoted-subject:" + i),
						PREDICATE,
						VF.createLiteral("quoted-object-" + i + "-" + "q".repeat(VALUE_LENGTH)));
				connection.add(VF.createIRI("urn:lmdb-autogrow:quoted-owner:" + i), PREDICATE, quoted);
			}
			connection.commit();
		}
		return count;
	}

	private static void addRows(SailRepositoryConnection connection, String subjectPrefix, String valuePrefix,
			int start, int count) {
		for (int i = start; i < start + count; i++) {
			connection.add(VF.createIRI("urn:lmdb-autogrow:" + subjectPrefix + i), PREDICATE,
					VF.createLiteral(valuePrefix + i + "-" + "x".repeat(VALUE_LENGTH)));
		}
	}

	private static LmdbStoreConfig autoGrowConfig() {
		return new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(256L * 1024)
				.setValueDBSize(256L * 1024)
				.setAutoGrow(true)
				.setTripleTermIndexes("spoc");
	}

	private static int countRows(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			int count = 0;
			try (RepositoryResult<Statement> rows = connection.getStatements(null, PREDICATE, null, false)) {
				while (rows.hasNext()) {
					rows.next();
					count++;
				}
			}
			connection.commit();
			return count;
		}
	}

	private static final class ResizeLogCapture implements AutoCloseable {

		private final Logger tripleLogger = (Logger) LoggerFactory.getLogger(TripleStore.class);
		private final Logger valueLogger = (Logger) LoggerFactory.getLogger(ValueStore.class);
		private final Level previousTripleLevel = tripleLogger.getLevel();
		private final Level previousValueLevel = valueLogger.getLevel();
		private final boolean previousTripleAdditive = tripleLogger.isAdditive();
		private final boolean previousValueAdditive = valueLogger.isAdditive();
		private final ListAppender<ILoggingEvent> tripleAppender = new ListAppender<>();
		private final ListAppender<ILoggingEvent> valueAppender = new ListAppender<>();

		private ResizeLogCapture() {
			tripleLogger.setLevel(Level.DEBUG);
			tripleLogger.setAdditive(false);
			valueLogger.setLevel(Level.INFO);
			valueLogger.setAdditive(false);
			tripleAppender.start();
			valueAppender.start();
			tripleLogger.addAppender(tripleAppender);
			valueLogger.addAppender(valueAppender);
		}

		private static ResizeLogCapture open() {
			return new ResizeLogCapture();
		}

		private List<String> resizeMessages() {
			return List.of(tripleAppender, valueAppender)
					.stream()
					.flatMap(appender -> appender.list.stream())
					.map(ILoggingEvent::getFormattedMessage)
					.filter(message -> message.contains("resized map to") || message.contains("Resizing map from")
							|| message.contains("reserved triple map capacity"))
					.toList();
		}

		private List<String> valueResizeMessages() {
			return valueAppender.list.stream()
					.map(ILoggingEvent::getFormattedMessage)
					.filter(message -> message.contains("Resizing map from"))
					.toList();
		}

		private void clear() {
			tripleAppender.list.clear();
			valueAppender.list.clear();
		}

		@Override
		public void close() {
			tripleLogger.detachAppender(tripleAppender);
			valueLogger.detachAppender(valueAppender);
			tripleAppender.stop();
			valueAppender.stop();
			tripleLogger.setLevel(previousTripleLevel);
			tripleLogger.setAdditive(previousTripleAdditive);
			valueLogger.setLevel(previousValueLevel);
			valueLogger.setAdditive(previousValueAdditive);
		}
	}
}
